import { test, expect } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

test.describe('File Upload Size Validation', () => {
  const testDir = path.join(__dirname, 'test-files');
  const smallFilePath = path.join(testDir, 'small-file.txt');
  const largeFilePath = path.join(testDir, 'large-file.txt');

  test.beforeEach(async ({ page }) => {
    // Create test directory if it doesn't exist
    if (!fs.existsSync(testDir)) {
      fs.mkdirSync(testDir, { recursive: true });
    }

    // Create a small file (1MB)
    const smallFileContent = Buffer.alloc(1024 * 1024, 'a');
    fs.writeFileSync(smallFilePath, smallFileContent);

    // Create a large file (6MB - exceeds 5MB limit)
    const largeFileContent = Buffer.alloc(6 * 1024 * 1024, 'b');
    fs.writeFileSync(largeFilePath, largeFileContent);

    // Navigate to the file upload page
    await page.goto('about:blank');

    // Create a simple HTML form for testing
    await page.setContent(`
      <html>
        <body>
          <form id="uploadForm">
            <label for="fileInput">Upload File</label>
            <input type="file" id="fileInput" name="file" accept=".txt,.pdf,.doc,.docx" />
            <button type="submit" id="submitBtn">Upload</button>
            <div id="errorMessage" style="color: red; display: none;"></div>
            <div id="successMessage" style="color: green; display: none;"></div>
          </form>
          <script>
            const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB
            const fileInput = document.getElementById('fileInput');
            const form = document.getElementById('uploadForm');
            const errorMessage = document.getElementById('errorMessage');
            const successMessage = document.getElementById('successMessage');
            const submitBtn = document.getElementById('submitBtn');

            fileInput.addEventListener('change', function(e) {
              errorMessage.style.display = 'none';
              successMessage.style.display = 'none';

              if (this.files.length > 0) {
                const file = this.files[0];
                if (file.size > MAX_FILE_SIZE) {
                  errorMessage.textContent = 'File size exceeds 5MB limit. Please upload a smaller file.';
                  errorMessage.style.display = 'block';
                  submitBtn.disabled = true;
                  this.value = '';
                } else {
                  successMessage.textContent = 'File selected successfully. Ready to upload.';
                  successMessage.style.display = 'block';
                  submitBtn.disabled = false;
                }
              }
            });

            form.addEventListener('submit', function(e) {
              e.preventDefault();
              if (fileInput.files.length > 0) {
                const file = fileInput.files[0];
                if (file.size <= MAX_FILE_SIZE) {
                  successMessage.textContent = 'File uploaded successfully!';
                  successMessage.style.display = 'block';
                  errorMessage.style.display = 'none';
                }
              }
            });
          </script>
        </body>
      </html>
    `);
  });

  test('should accept files smaller than 5MB', async ({ page }) => {
    // Get the file input element
    const fileInput = page.getByLabel('Upload File');

    // Upload the small file
    await fileInput.setInputFiles(smallFilePath);

    // Verify success message is displayed
    const successMessage = page.locator('#successMessage');
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('File selected successfully');

    // Verify error message is not displayed
    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).not.toBeVisible();

    // Verify submit button is enabled
    const submitBtn = page.getByRole('button', { name: 'Upload' });
    await expect(submitBtn).toBeEnabled();
  });

  test('should reject files larger than 5MB', async ({ page }) => {
    // Get the file input element
    const fileInput = page.getByLabel('Upload File');

    // Upload the large file
    await fileInput.setInputFiles(largeFilePath);

    // Verify error message is displayed
    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('File size exceeds 5MB limit');

    // Verify success message is not displayed
    const successMessage = page.locator('#successMessage');
    await expect(successMessage).not.toBeVisible();

    // Verify submit button is disabled
    const submitBtn = page.getByRole('button', { name: 'Upload' });
    await expect(submitBtn).toBeDisabled();

    // Verify file input is cleared
    const files = await fileInput.inputValue();
    expect(files).toBe('');
  });

  test('should allow file replacement after rejection', async ({ page }) => {
    // Get the file input element
    const fileInput = page.getByLabel('Upload File');

    // First, upload the large file
    await fileInput.setInputFiles(largeFilePath);

    // Verify error message is displayed
    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toBeVisible();

    // Now upload the small file to replace it
    await fileInput.setInputFiles(smallFilePath);

    // Verify error message is hidden
    await expect(errorMessage).not.toBeVisible();

    // Verify success message is displayed
    const successMessage = page.locator('#successMessage');
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('File selected successfully');

    // Verify submit button is enabled
    const submitBtn = page.getByRole('button', { name: 'Upload' });
    await expect(submitBtn).toBeEnabled();
  });

  test('should validate file size on form submission', async ({ page }) => {
    // Get the file input element
    const fileInput = page.getByLabel('Upload File');

    // Upload the small file
    await fileInput.setInputFiles(smallFilePath);

    // Click the submit button
    const submitBtn = page.getByRole('button', { name: 'Upload' });
    await submitBtn.click();

    // Verify success message is displayed after submission
    const successMessage = page.locator('#successMessage');
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('File uploaded successfully');
  });

  test('should display specific error message for oversized files', async ({ page }) => {
    // Get the file input element
    const fileInput = page.getByLabel('Upload File');

    // Upload the large file
    await fileInput.setInputFiles(largeFilePath);

    // Verify the specific error message text
    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toHaveText('File size exceeds 5MB limit. Please upload a smaller file.');
  });
});
